paragrafos:
Cada tarefa vira um objeto: { texto: "Estudar", feita: false }. A lista começa com o que está salvo, ou vazia na primeira vez:
let tarefas = JSON.parse(localStorage.getItem("tarefas")) || [];
function salvar() {
  localStorage.setItem("tarefas", JSON.stringify(tarefas));
}

A função adicionar agora coloca o objeto na lista, salva e redesenha:
function adicionar() {
  const texto = campo.value.trim();
  if (texto === "") return;
  tarefas.push({ texto: texto, feita: false });
  salvar();
  desenhar();
  campo.value = "";
}

A função desenhar apaga a lista da tela e cria um li para cada tarefa. Clicar no item troca feita entre true e false; o botão Remover tira a tarefa com splice:
function desenhar() {
  lista.innerHTML = "";
  tarefas.forEach((t, i) => {
    const item = document.createElement("li");
    item.textContent = t.texto;
    if (t.feita) item.classList.add("feita");
    item.addEventListener("click", () => { t.feita = !t.feita; salvar(); desenhar(); });
    const x = document.createElement("button");
    x.textContent = "Remover";
    x.addEventListener("click", (e) => { e.stopPropagation(); tarefas.splice(i, 1); salvar(); desenhar(); });
    item.appendChild(x);
    lista.appendChild(item);
  });
}
desenhar();
